  "{e} is null: it doesn't point to any object. Create one with new before using it, or check if ({e} != null).": { ca: "{e} és null: no apunta a cap objecte. Crea'n un amb new abans de fer-lo servir, o comprova if ({e} != null).", es: "{e} es null: no apunta a ningún objeto. Crea uno con new antes de usarlo, o comprueba if ({e} != null)." },
  "{e} is null: create the object with new first.": { ca: "{e} és null: primer crea l'objecte amb new.", es: "{e} es null: primero crea el objeto con new." },
