  "{w} has {n} item (Count): positions 0 to {l}. You asked for position {i}.": { ca: "{w} té {n} element (Count): posició 0. Has demanat la posició {i}.", es: "{w} tiene {n} elemento (Count): posición 0. Has pedido la posición {i}." },
